// ==========================================================================
//  npu_weights_pkg.sv
//  NPU egitilmis agirliklari, sapmalari ve softmax bakis tablosu
//
//  BU DOSYA URETILMISTIR - ELLE DUZENLEMEYIN.
//      python scripts/gen_rom_paketleri.py
//  Tutarlilik denetimi:
//      python scripts/gen_rom_paketleri.py --denetle
//
//  Tablolar packed vektorde tutulur, erisim dilimleme ile
//  yapilir. Indeks 0 vektorun EN DUSUK bitlerindedir.
//
//  fc_weights DORDE BOLUNMUSTUR (fc_weights0..3). NPU'nun FC
//  katmani dort sinif icin ayrik araliklardan okur; tek buyuk
//  ROM adres cozucusunde 4.694 fanout uretiyordu.
// ==========================================================================

package npu_weights_pkg;

    // weights/dw_weights.mem
    //   640 giris x 8 bit = 5120 bit (isaretli)

    localparam logic [5119:0] DW_WEIGHTS_DUZ = 5120';

    function automatic logic signed [7:0] dw_weights(input logic [9:0] i);
        return DW_WEIGHTS_DUZ[i * 8 +: 8];
    endfunction

    // weights/dw_bias.mem
    //   8 giris x 32 bit = 256 bit (isaretli)

    localparam logic [255:0] DW_BIAS_DUZ = 256'hfffffd4afffffb4f0000000600000052000000d0ffffffd0000000a9fffffe8a;

    function automatic logic signed [31:0] dw_bias(input logic [2:0] i);
        return DW_BIAS_DUZ[i * 32 +: 32];
    endfunction

    // weights/fc_weights.mem
    //   16000 giris x 8 bit = 128000 bit (isaretli)
    //   4 BOLUM x 4000 giris - fanout icin ayrildi

    // --- bolum 0: indeks 0..3999 ---
    localparam logic [31999:0] FC_WEIGHTS0_DUZ = 32000';

`ifdef NPU_WEIGHTS_STUB
    // OLCUM DENEYI - gercek tablo yerine adresten turetilen
    // ucuz bir deger. Veri yolu canli kalir, ROM yok.
    function automatic logic signed [7:0] fc_weights0(input logic [11:0] i);
        return 8'(i);
    endfunction
`else
    function automatic logic signed [7:0] fc_weights0(input logic [11:0] i);
        return FC_WEIGHTS0_DUZ[i * 8 +: 8];
    endfunction
`endif

    // --- bolum 1: indeks 4000..7999 ---
    localparam logic [31999:0] FC_WEIGHTS1_DUZ = 32000';

`ifdef NPU_WEIGHTS_STUB
    // OLCUM DENEYI - gercek tablo yerine adresten turetilen
    // ucuz bir deger. Veri yolu canli kalir, ROM yok.
    function automatic logic signed [7:0] fc_weights1(input logic [11:0] i);
        return 8'(i);
    endfunction
`else
    function automatic logic signed [7:0] fc_weights1(input logic [11:0] i);
        return FC_WEIGHTS1_DUZ[i * 8 +: 8];
    endfunction
`endif

    // --- bolum 2: indeks 8000..11999 ---
    localparam logic [31999:0] FC_WEIGHTS2_DUZ = 32000';

`ifdef NPU_WEIGHTS_STUB
    // OLCUM DENEYI - gercek tablo yerine adresten turetilen
    // ucuz bir deger. Veri yolu canli kalir, ROM yok.
    function automatic logic signed [7:0] fc_weights2(input logic [11:0] i);
        return 8'(i);
    endfunction
`else
    function automatic logic signed [7:0] fc_weights2(input logic [11:0] i);
        return FC_WEIGHTS2_DUZ[i * 8 +: 8];
    endfunction
`endif

    // --- bolum 3: indeks 12000..15999 ---
    localparam logic [31999:0] FC_WEIGHTS3_DUZ = 32000';

`ifdef NPU_WEIGHTS_STUB
    // OLCUM DENEYI - gercek tablo yerine adresten turetilen
    // ucuz bir deger. Veri yolu canli kalir, ROM yok.
    function automatic logic signed [7:0] fc_weights3(input logic [11:0] i);
        return 8'(i);
    endfunction
`else
    function automatic logic signed [7:0] fc_weights3(input logic [11:0] i);
        return FC_WEIGHTS3_DUZ[i * 8 +: 8];
    endfunction
`endif

    // weights/fc_bias.mem
    //   4 giris x 32 bit = 128 bit (isaretli)

    localparam logic [127:0] FC_BIAS_DUZ = 128'h000000baffffffa2fffffdfa000001ab;

    function automatic logic signed [31:0] fc_bias(input logic [1:0] i);
        return FC_BIAS_DUZ[i * 32 +: 32];
    endfunction

    // weights/softmax_exp_lut.mem
    //   256 giris x 13 bit = 3328 bit

    localparam logic [3327:0] SOFTMAX_EXP_LUT_DUZ = 3328';

    function automatic logic [12:0] softmax_exp_lut(input logic [7:0] i);
        return SOFTMAX_EXP_LUT_DUZ[i * 13 +: 13];
    endfunction

endpackage
